#include <cstdio>
#include <algorithm>
using namespace std;

typedef long long ll;

int main() {
    ll i, n, num, len, p;
    while (scanf("%lld", &n), n) {
        num = n; 
        len = 0;
        ll l[100000];
        // Read all inputs in one go to minimize I/O calls
        for (i = 0; i < n; i++) {
            scanf("%lld", &p); 
            len += p;
        }
        // Read l values
        for (i = 0; i < n - 1; i++) {
            scanf("%lld", &l[i]);
        }
        sort(l, l + n - 1);
        // Combine calculations into a single loop
        for (i = n - 2; i >= 0; i--) {
            if ((num - 1) * (len + l[i]) < num * len) break;
            num--; 
            len += l[i];
        }
        printf("%lld\n", num * len);
    }
}

